function allocationSelect(array $t):string {
    $incoming=(int)$t['credit']>0;
    $key=$incoming?'registration_id':'expense_id';
    $rows=$incoming?all("SELECT r.id,r.amount,u.name FROM registrations r JOIN users u ON u.id=r.user_id WHERE r.status<>'cancelled' ORDER BY r.id"):all("SELECT id,amount,payee AS name FROM expenses WHERE status='approved' ORDER BY id");
    $html='<label class="field">'.($incoming?'割当先の申込':'照合する承認済経費').'<select name="'.$key.'" required><option value="">選択してください</option>';
    foreach($rows as $row){$remaining=(int)$row['amount']-($incoming?paidRegistration((int)$row['id']):paidExpense((int)$row['id']));if(!$incoming&&$remaining<=0)continue;$match=$remaining===max((int)$t['credit'],(int)$t['debit'])-usedBank((int)$t['id']);$html.='<option value="'.$row['id'].'">'.h('#'.$row['id'].' '.$row['name'].' 未照合 '.yen($remaining).($match?'（金額一致・参考）':'')).'</option>';}
    return $html.'</select></label>';
}
