 elseif($page==='admin_accounting'){$s=setting();$tot=one("SELECT COALESCE(SUM(credit),0) inc,COALESCE(SUM(debit),0) exp FROM bank_transactions WHERE state='confirmed'");$es=all('SELECT e.*,u.name FROM expenses e JOIN users u ON u.id=e.user_id ORDER BY e.id DESC');$unpaid=0;$rows=[];foreach($es as $e){$paid=paidExpense((int)$e['id']);if($e['status']==='approved')$unpaid+=(int)$e['amount']-$paid;$files=all("SELECT id FROM private_files WHERE expense_id=? AND kind='receipt'",[$e['id']]);$receipts=implode(' ',array_map(fn($f)=>'<a href="?page=file&id='.$f['id'].'">領収書</a>',$files));$buttons=$e['status']==='submitted'?form('approve_expense',hidden('id',$e['id']).reasons().button('別の幹事が承認')):'承認済';$rows[]=['#'.$e['id'].' '.h($e['expense_date']),h($e['name']).'<br>'.h($e['payee']),h($e['category']).'<br>'.h($e['purpose']),yen((int)$e['amount']).'<br>未精算 '.yen((int)$e['amount']-$paid),$receipts?:'未添付',$buttons];}echo '<h1>会計・収支</h1>'.grid([['口座入金（確認済）',yen((int)$tot['inc'])],['口座出金（確認済）',yen((int)$tot['exp'])],['帳簿残高（開始残高＋入出金）',yen((int)$s['opening']+(int)$tot['inc']-(int)$tot['exp'])],['承認済経費の未精算',yen($unpaid)]]).'<div class="panel"><h2>経費・立替を申請する</h2><p>申請だけでは口座残高は変わりません。銀行明細との照合は「銀行CSV」で行います。</p>'.form('expense','<div class="grid-2">'.input('date','利用日',date('Y-m-d'),'date').input('category','費目').input('payee','支払先').input('purpose','用途').input('amount','金額（円）','','number').reasons().'</div><label class="field">領収書（任意・JPEG/PNG/PDF・5MB以下）<input type="file" name="receipt" accept="image/jpeg,image/png,application/pdf"></label>'.button('経費を申請'),true).'</div><a class="btn btn-outline" href="?page=export&kind=finance">経費CSV</a> <a class="btn btn-outline" href="?page=export&kind=cashbook">銀行入出金・収支CSV</a>'.tabler(['経費','申請者・支払先','費目・用途','金額','添付','承認'],$rows);}
 elseif($page==='admin_bank'){echo '<h1>銀行CSV・入出金照合</h1><div class="panel"><p>元CSVを保持し、担当者が確認してから入出金を割り当てます。摘要の振込名義は推測で確定しません。</p>'.form('import','<label class="file-drop">UFJ形式CSV（UTF-8/Shift-JIS、1.5MB以下）<input type="file" name="csv" accept=".csv" required></label>'.button('CSVを取り込む'),true).'</div>';foreach(all('SELECT id,filename,report_json FROM bank_imports ORDER BY id DESC') as $i)echo '<details><summary>取込 #'.$i['id'].' '.h($i['filename']).'</summary><pre>'.h(json_encode(obj($i['report_json']),JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)).'</pre></details>';$rows=[];foreach(all('SELECT * FROM bank_transactions ORDER BY id DESC') as $t){$id=(int)$t['id'];$ctl='';if($t['state']==='pending')$ctl=form('bank_decide',hidden('id',$id).'<select name="state"><option value="confirmed">重複・区分を確認して確定</option><option value="excluded">重複・対象外として除外</option></select>'.reasons().button('判定'));if($t['state']==='confirmed'){$target=(int)$t['credit']>0?'registration_id':'expense_id';$ctl.=form('allocate',hidden('bank_id',$id).allocationSelect($t).input('amount','割当額','','number').reasons().button('割当・照合を記録'));}$rows[]=['#'.$id.' '.h($t['txn_date']),h($t['memo']).'<br><small>'.h($t['review']).'</small>',yen((int)$t['credit']).' / '.yen((int)$t['debit']),yen((int)$t['balance']),yen(max((int)$t['credit'],(int)$t['debit'])-usedBank($id)),h(['pending'=>'確認待ち','confirmed'=>'確認済','excluded'=>'除外済'][$t['state']]??$t['state']),$ctl];}echo tabler(['明細','摘要・注意','入金 / 出金','明細残高','未割当','状態','操作'],$rows);echo '<h2>割当・照合の履歴</h2>'.tabler(['ID','明細','申込 / 経費','額','状態','操作'],array_map(fn($a)=>['#'.$a['id'],'#'.$a['bank_id'],h($a['registration_id']??'—').' / '.h($a['expense_id']??'—'),yen((int)$a['amount']),(int)$a['active']?'有効':'取消済',(int)$a['active']?form('reverse',hidden('id',$a['id']).reasons().button('理由を付けて取消')):''],all('SELECT * FROM allocations ORDER BY id DESC')));}
 elseif($page==='admin_photos'){echo photoManagementView();}
 elseif($page==='admin_contacts'){echo contactsAdminView();}
 elseif($page==='admin_inquiries'){echo inquiryAdminView();}
 elseif($page==='admin_mail'){echo outboxView().broadcastOutboxView();}
 elseif($page==='admin_broadcast'){echo broadcastView();}
 elseif($page==='admin_logs'){echo '<h1>管理・入出金操作ログ</h1><a class="btn" href="?page=export&kind=logs">ログCSV</a>'.tabler(['日時','担当者ID','操作・対象','理由','変更前後'],array_map(fn($l)=>[h($l['created']),h($l['actor_id']),h($l['action']).'<br>'.h($l['entity']),h($l['reason']),'<details><summary>内容</summary><pre>'.h($l['before_json']).'<br>'.h($l['after_json']).'</pre></details>'],all('SELECT * FROM audit_logs ORDER BY id DESC LIMIT 500')));}
 elseif($page==='admin_settings'){$s=setting();$fields='';foreach(['dateLabel'=>'開催日表示','venue'=>'会場','fee'=>'会費（新規申込から適用）','classSize'=>'参加状況グラフの基準人数（1クラス・仮）','capacity'=>'参加定員（会場上限）','opening'=>'口座開始残高','open'=>'受付開始日','registration'=>'申込期限','payment'=>'入金期限','change'=>'変更期限','cancel'=>'キャンセル期限','photoEnd'=>'写真公開終了日'] as $k=>$label)$fields.=input($k,$label,$s[$k],in_array($k,['fee','capacity','opening','classSize'])?'number':(in_array($k,['dateLabel','venue'])?'text':'date'));echo '<div class="panel"><h1>大会・期限設定</h1><p>日程・会費・期限は未確定の仮値です。会費を変えても既存請求額は上書きしません。</p>'.form('settings','<div class="grid-2">'.$fields.'</div>'.reasons().button('理由を付けて保存')).'</div>';}
 else {http_response_code(404);echo '<h1>ページがありません。</h1>';}
 $body=ob_get_clean();
}catch(DomainException $e){if(ob_get_level())ob_end_clean();http_response_code(403);$body='<div class="panel"><h1>このページは開けません。</h1><p>'.h($e->getMessage()).'</p><a class="btn" href="?page=login">ログインへ</a></div>';}
